// BApplication::BApplication(const char* signature, status_t* error)
BApplication*
mojobe_BApplication_new(const char* a_signature, status_t* a_error)
{
	status_t status = B_NO_MEMORY;
	BApplication* object = new(std::nothrow) BApplication(a_signature, &status);
	if (object != NULL && status != B_OK) {
		delete object;
		object = NULL;
	}
	if (a_error != NULL)
		*a_error = status;
	return object;
}


// BApplication::BApplication(const char* signature, status_t* error), as a MojoBApplication
BApplication*
mojobe_MojoBApplication_new(const char* a_signature,
	status_t* a_error,
	const mojobe_BApplication_hooks* hooks,
	void* context)
{
	status_t status = B_NO_MEMORY;
	BApplication* object = new(std::nothrow) MojoBApplication(a_signature, &status, hooks, context);
	if (object != NULL && status != B_OK) {
		delete object;
		object = NULL;
	}
	if (a_error != NULL)
		*a_error = status;
	return object;
}


